def second_largest(xs: list[int]) -> int | None:
    assert isinstance(xs, list), 'xs must be a list'
    assert all((isinstance(x, int) for x in xs)), 'all elements must be ints'
    assert len(set(xs)) == len(xs), 'all elements must be different'
    if len(xs) < 2:
        result = None
        assert result is None
        return result
    largest, second = (xs[0], xs[1]) if xs[0] > xs[1] else (xs[1], xs[0])
    for x in xs[2:]:
        if x > largest:
            if x > second:
                second = x
        else:
            largest, second = (x, largest)
    assert second in xs
    assert all((second >= x or x == largest for x in xs))
    return second

